package com.tiviloom.mobile.test;
import android.app.*;import android.content.*;import android.content.pm.ActivityInfo;import android.os.*;import android.view.*;import android.webkit.*;import org.json.*;import java.lang.reflect.*;import java.util.concurrent.*;

/** Runs against the real installed Activity/WebView. No production test bridge. */
public class NavigationTest extends Instrumentation {
 Activity activity;WebView web;int passed=0,failed=0;StringBuilder report=new StringBuilder();
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 String eval(String js)throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] value={"null"};runOnMainSync(()->web.evaluateJavascript(js,v->{value[0]=v;latch.countDown();}));if(!latch.await(20,TimeUnit.SECONDS))throw new AssertionError("WebView JS timeout");return value[0];}
 void waitFor(String js)throws Exception{waitFor(js,20000);} void waitFor(String js,long timeout)throws Exception{long until=SystemClock.uptimeMillis()+timeout;while(SystemClock.uptimeMillis()<until){if("true".equals(eval(js)))return;Thread.sleep(150);}throw new AssertionError("Condition timed out: "+js);}
 void require(String js)throws Exception{if(!"true".equals(eval(js)))throw new AssertionError("Failed: "+js);}
 void visualReady()throws Exception{CountDownLatch ready=new CountDownLatch(1);runOnMainSync(()->web.postVisualStateCallback(SystemClock.uptimeMillis(),new WebView.VisualStateCallback(){@Override public void onComplete(long requestId){web.invalidate();ready.countDown();}}));if(!ready.await(20,TimeUnit.SECONDS))throw new AssertionError("WebView visual state timeout");SystemClock.sleep(150);}
 void tap(String selector)throws Exception{tapAt(selector,.5,.5);}
 void tapAt(String selector,double fx,double fy)throws Exception{waitFor("(function(){const e=document.querySelector("+JSONObject.quote(selector)+");if(!e)return false;e.scrollIntoView({block:'nearest'});const r=e.getBoundingClientRect(),hit=document.elementFromPoint(r.left+r.width*"+fx+",r.top+r.height*"+fy+");return !!r.width&&!!r.height&&!!hit&&e.contains(hit);})()");visualReady();String value=eval("(function(){const e=document.querySelector("+JSONObject.quote(selector)+");if(!e)throw Error('Missing test target');e.scrollIntoView({block:'nearest'});const r=e.getBoundingClientRect();const x=r.left+r.width*"+fx+",y=r.top+r.height*"+fy+";const hit=document.elementFromPoint(x,y);if(!hit||!e.contains(hit))throw Error('Covered test target: '+e.id+' by '+hit?.outerHTML?.slice(0,200));return JSON.stringify({x,y,w:innerWidth});})()");String json=(String)new JSONTokener(value).nextValue();JSONObject p=new JSONObject(json);int[] loc=new int[2];runOnMainSync(()->web.getLocationOnScreen(loc));float scale=web.getWidth()/(float)p.getDouble("w"),x=loc[0]+(float)p.getDouble("x")*scale,y=loc[1]+(float)p.getDouble("y")*scale;long now=SystemClock.uptimeMillis();sendPointerSync(MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,x,y,0));sendPointerSync(MotionEvent.obtain(now,now+60,MotionEvent.ACTION_UP,x,y,0));Thread.sleep(250);}
 void back()throws Exception{sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);Thread.sleep(300);}
 interface Check{void run()throws Exception;}
 void capture(String name){try{visualReady();SystemClock.sleep(2500);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image==null)return;java.io.File folder=new java.io.File(getTargetContext().getExternalFilesDir(null),"navigation-tests");folder.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(folder,name.replaceAll("[^a-zA-Z0-9]+","-")+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}catch(Exception ignored){}}
 void check(String name,Check f){int reportStart=report.length();try{f.run();passed++;report.append("PASS ").append(name).append('\n');}catch(Throwable e){failed++;report.append("FAIL ").append(name).append(" — ").append(e.toString()).append('\n');try{report.append("DOM ").append(eval("JSON.stringify({url:location.href,ready:document.readyState,html:document.documentElement.className,body:document.body?.innerText?.slice(0,1000)})")).append('\n');}catch(Throwable ignored){}}capture(name);Bundle b=new Bundle();b.putString("stream",report.substring(reportStart));sendStatus(0,b);}
 void bounded()throws Exception{report.append("BOUNDS ").append(eval("JSON.stringify({w:innerWidth,boxes:Array.from(document.querySelectorAll('#mobile-header,.rail,#content')).map(e=>({id:e.id,cls:e.className,rect:e.getBoundingClientRect().toJSON()}))})")).append('\n');require("(function(){return ['#mobile-header','.rail','#content','.dialog','.wizard','#search-input','.movie-description'].every(s=>Array.from(document.querySelectorAll(s)).every(e=>{const r=e.getBoundingClientRect();if(!r.width||!r.height||e.closest('[hidden]'))return true;return r.left>=-1&&r.right<=innerWidth+1;}));})()");}
 @Override public void onStart(){try{activity=startActivitySync(new Intent(Intent.ACTION_MAIN).setClassName("com.tiviloom.mobile","com.tiviloom.mobile.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Field field=activity.getClass().getDeclaredField("web");field.setAccessible(true);web=(WebView)field.get(activity);waitFor("!!document.querySelector('#welcome') && document.querySelector('#boot').hidden",90000);
 // Seed a local, reproducible playlist using the normal persistent library schema.
 eval("(function(){localStorage.clear();localStorage.setItem('tl-tv-ready','true');localStorage.setItem('tl-prefs',JSON.stringify({autoplay:false,groups:true,motion:false,muted:true,fit:'contain'}));const channels=[{id:'one',name:'Loom One',type:'tv',group:'News',demo:true,url:'assets/demo.mp4'},{id:'two',name:'Loom Two',type:'tv',group:'Sports',demo:true,url:'assets/demo.mp4'},{id:'film',name:'Test Movie',type:'movie',group:'Movies',demo:true,url:'assets/demo.mp4',poster:'assets/poster-0.svg'},{id:'ep1',name:'Example S01E01',seriesShowName:'Example',season:1,episode:1,type:'series',group:'Series',demo:true,url:'assets/demo.mp4',poster:'assets/poster-0.svg'},{id:'ep2',name:'Example S01E02',seriesShowName:'Example',season:1,episode:2,type:'series',group:'Series',demo:true,url:'assets/demo.mp4'}];const fixtureID='navigation-'+Date.now();const r=indexedDB.open('TiviLoom',1);r.onupgradeneeded=()=>r.result.createObjectStore('library');r.onsuccess=()=>{const tx=r.result.transaction('library','readwrite');tx.objectStore('library').put({version:2,activeId:fixtureID,playlists:[{id:fixtureID,name:'Navigation fixture',imported:true,channels,programs:[],favorites:[],history:[],groupPins:{},groupNames:{}}]},'active');tx.oncomplete=()=>{r.result.close();window.__fixtureReady=true;};};})()");waitFor("window.__fixtureReady===true");eval("window.__reloadPending=true;location.reload()");waitFor("!window.__reloadPending && !!document.querySelector('[data-channel=one]') && document.querySelector('#boot').hidden",90000);
 check("startup phone layout and narrow bounds",()->{require("document.documentElement.classList.contains('phone')");bounded();});
 check("one channel tap stays in preview",()->{tap("[data-channel=one]");waitFor("document.querySelector('#video').dataset.tiviSource==='assets/demo.mp4'");require("document.querySelector('#player').hidden");});
 check("same channel repeat stays in preview",()->{tap("[data-channel=one]");require("document.querySelector('#player').hidden");});
 check("switch channel stays in preview",()->{tap("[data-channel=two]");require("document.querySelector('#player').hidden");});
 check("offline sample video actually advances",()->{waitFor("document.querySelector('#video').currentTime>0");});
 check("dedicated expand button enters fullscreen and Back returns",()->{tap("#preview-play");waitFor("!document.querySelector('#player').hidden");waitFor("document.querySelector('#video-surface').getBoundingClientRect().height>=innerHeight-2 && document.querySelector('#video-surface').getBoundingClientRect().width>=innerWidth-2");capture("fullscreen-open");back();waitFor("document.querySelector('#player').hidden");});
 check("groups open, selection filters and closes drawer",()->{tap("[data-tv=groups]");waitFor("document.querySelector('#app').dataset.nav==='1'");capture("groups-drawer-open");tap("[data-group=News]");waitFor("document.querySelector('#app').dataset.nav==='0'");require("document.querySelectorAll('[data-channel]').length===1");});
 check("drawer scrim closes without changing route",()->{tap("[data-tv=groups]");tapAt("#phone-group-scrim",.98,.5);waitFor("document.querySelector('#app').dataset.nav==='0'");});
 check("movie detail and native Back",()->{tap("[data-tv=nav-movies]");tap("[data-movie=film]");waitFor("!!document.querySelector('#movie-detail')");bounded();waitFor("!!document.elementFromPoint(innerWidth/2,innerHeight/2)?.closest('#movie-detail')");capture("movie-details-open");back();waitFor("!document.querySelector('#movie-detail')");});
 check("Series seasons and episodes",()->{tap("[data-tv=nav-series]");tap("[data-series]");waitFor("!!document.querySelector('[data-tv=series-episode]')");require("document.querySelectorAll('[data-tv=series-episode]').length===2");capture("series-episodes-open");back();});
 check("search preserves native input node and routes series results",()->{tap("[data-tv=nav-search]");tap("#search-input");eval("window.__input=document.querySelector('#search-input');window.__input.value='Example';window.__input.dispatchEvent(new Event('input',{bubbles:true}))");require("document.querySelector('#search-input')===window.__input");require("document.querySelectorAll('[data-result]').length===2");runOnMainSync(()->((android.view.inputmethod.InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(web.getWindowToken(),0));capture("search-results-open");tap("[data-result=ep1]");waitFor("!!document.querySelector('[data-tv=series-episode]')");back();});
 check("settings Back stack",()->{tap("[data-tv=settings]");tap("[data-tv=setting-sources]");waitFor("!!document.querySelector('.playlist-row')");capture("playlist-settings-open");back();waitFor("document.querySelector('#modal-root').textContent.includes('Settings')");back();waitFor("document.querySelector('#modal-root').children.length===0");});
 check("landscape menu and bounds",()->{runOnMainSync(()->activity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));waitFor("innerWidth>innerHeight");tap("[data-tv=nav-guide]");bounded();tap("[data-tv=groups]");tap("[data-group='Hamısı']");waitFor("document.querySelector('#app').dataset.nav==='0'");bounded();});
 check("portrait returns cleanly",()->{runOnMainSync(()->activity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));waitFor("innerHeight>innerWidth");bounded();require("document.querySelector('#player').hidden");});
 check("native HTTP playlist import, durable save and preview route",()->{
  final java.net.ServerSocket server=new java.net.ServerSocket(0,10,java.net.InetAddress.getByName("127.0.0.1"));
  Thread provider=new Thread(()->{try(java.net.Socket client=server.accept()){java.io.BufferedReader reader=new java.io.BufferedReader(new java.io.InputStreamReader(client.getInputStream(),"UTF-8"));String line;while((line=reader.readLine())!=null&&!line.isEmpty()){}String playlist="#EXTM3U\n#EXTINF:-1 group-title=\"Fixture\",Fixture One\nhttps://appassets.androidplatform.net/assets/demo.mp4\n";byte[] body=playlist.getBytes("UTF-8");java.io.OutputStream out=client.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: "+body.length+"\r\nConnection: close\r\n\r\n").getBytes("UTF-8"));out.write(body);out.flush();}catch(Exception ignored){}});provider.setDaemon(true);provider.start();
  try{tap("[data-tv=settings]");tap("[data-tv=setting-sources]");tap("[data-tv=import]");tap("[data-tv=type-m3u]");tap("[data-tv=edit-url]");eval("const f=document.querySelector('#wizard-field');f.value='http://127.0.0.1:"+server.getLocalPort()+"/list.m3u';f.dispatchEvent(new Event('input',{bubbles:true}));f.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true}));");runOnMainSync(()->((android.view.inputmethod.InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(web.getWindowToken(),0));tap("[data-tv=wizard-next]");waitFor("!!document.querySelector('[data-tv=mode-tv]')");tap("[data-tv=wizard-next]");waitFor("document.querySelector('#wizard').textContent.includes('EPG URL')");tap("[data-tv=wizard-next]");waitFor("document.querySelector('#wizard').hidden && !!document.querySelector('.channel-name') && document.querySelector('.channel-name').textContent.includes('Fixture One')");eval("window.__reloadPending=true;location.reload()");waitFor("!window.__reloadPending && document.querySelector('#boot').hidden && !!document.querySelector('.channel-name') && document.querySelector('.channel-name').textContent.includes('Fixture One')",90000);tap(".channel-name");require("document.querySelector('#player').hidden");bounded();}finally{server.close();}
 });
 }catch(Throwable e){failed++;capture("FATAL");report.append("FATAL ").append(e.toString()).append('\n');try{report.append("DOM ").append(eval("JSON.stringify({url:location.href,ready:document.readyState,boot:document.querySelector('#boot')?.outerHTML,body:document.body?.innerText?.slice(0,1800)})")).append('\n');}catch(Throwable ignored){}}Bundle result=new Bundle();result.putString("stream",report.toString()+"\nTOTAL "+passed+" passed, "+failed+" failed\n");result.putInt("passed",passed);result.putInt("failed",failed);finish(failed==0?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
